head.script:
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.bns.BnsPanelToGroupBox(panel_Top);

        // DR 및 Exa DB체크
        if (js_svrGubun === 'dr') {
            await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
            // return false;

        } else {
            $c.bns.fn_BnsCheckExaDb("ULDBNS20400.xml", dts_ExaYn, '1');
            // return false;

        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        scwin.showIsur(img_com_srch);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20400.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20400.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadError
 * @description dts_List_1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_1_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20400.dts_List_1_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20400.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name dts_List_1_OnLoadCompleted
 * @description dts_List_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20400.dts_List_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeypress
 * @description txb_isur_cd onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_isur_cd_onkeypress = async function() {
    try {
        if (window.event.keyCode === 13) await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20400.txb_isur_cd_onkeypress" });
    }
};

/**
 * @method
 * @name btn_ToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToExcel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDBNS20400.xml", SCREN_PROCS_TP_CD_07, '');
        const title = '수수료면제거래소회원';
        const fileNm = $c.ut.cGetToday('yyyymmdd') + '_' + title;
        $c.data.downloadGridViewExcel(grd_List, {fileName: title, type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20400.btn_ToExcel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_FEE_EXMPT_MBR_LIST";
    url += "&queryId=lds.stf.bnsfee_exmpt_mbr.select.list";
    url += "&SCREN_ID=" + "ULDBNS20400.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_VAL=" + txb_isur_cd.getValue(); // txb_isur_cd txb_com_abbrv;
    url += "&{P}V_REG_YN=" + cmb_REG_YN.getValue(); // 회원여부

    const sbmOptions = {
        id : "sbm_dts_List_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return url;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_isur_cd.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_com_abbrv.setValue(arrPar[0].ISUR_NM);
    txb_isur_cd.setValue(arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {*} img_com_srch img_com_srch
 * @returns {void}
 * @hidden N
 */
scwin.showIsur = function(img_com_srch) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(img_com_srch);
};
